// Create limit range
const prodLimits = new k8s.core.v1.LimitRange("prod-limits", {
    metadata: {
        name: "resource-limits",
        namespace: prodNamespace.metadata.name,
    },
    spec: {
        limits: [
            {
                type: "Container",
                default: {
